const publishLifecycleDatasetVersion = `-- name: PublishLifecycleDatasetVersion :one
WITH target AS (
    SELECT
        dataset_id
    FROM
        dataset_versions
    WHERE
        id = $2
        AND STATUS = 'SUBMITTED' FOR
    UPDATE
),
archived AS (
    UPDATE
        dataset_versions
    SET
        STATUS = 'ARCHIVED',
        archived_by = $1,
        archived_at = NOW()
    WHERE
        dataset_id = (
            SELECT
                dataset_id
            FROM
                target
        )
        AND STATUS = 'PUBLISHED'
)
UPDATE
    dataset_versions
SET
    STATUS = 'PUBLISHED',
    published_by = $1,
    published_at = NOW(),
    rejected_by = NULL,
    rejected_at = NULL,
    rejection_note = NULL
WHERE
    dataset_versions.id = $2
    AND dataset_versions.status = 'SUBMITTED'
RETURNING
    id, dataset_id, status, revision, title, description, keywords, accrual_periodicity, quality_annotation, access_right, source_created_at, source_updated_at, spatial_point, spatial_polygon, temporal_start, temporal_end, created_by, created_at, updated_at, submitted_by, submitted_at, published_by, published_at, archived_by, archived_at, rejected_by, rejected_at, rejection_note
`

